package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type EmpRec struct {
	ErId    string
	ErDept  string
	ErHours decimal.Decimal
	ErRate  decimal.Decimal
}

var WsEofFlag string
var WsFirstFlag string
var WsPrevDept string
var WsRegHours decimal.Decimal
var WsOtHours decimal.Decimal
var WsGross decimal.Decimal
var WsDeptTotal decimal.Decimal
var WsDeptCount int64
var WsGrandTotal decimal.Decimal
var WsGrandCount int64
var WsHoursEd string
var WsRateEd string
var WsGrossEd string
var WsDeptEd string
var WsGrandEd string

var empFile *os.File
var empReader *bufio.Reader
var EmpRecVar EmpRec

func main() {
	// initial values from WORKING-STORAGE
	WsEofFlag = "N"
	WsFirstFlag = "Y"
	WsPrevDept = "   "
	WsRegHours = decimal.NewFromInt(0)
	WsOtHours = decimal.NewFromInt(0)
	WsGross = decimal.NewFromInt(0)
	WsDeptTotal = decimal.NewFromInt(0)
	WsDeptCount = 0
	WsGrandTotal = decimal.NewFromInt(0)
	WsGrandCount = 0

	MAIN_PARA()
}

func MAIN_PARA() {
	OPEN_EMP()
	READ_PARA()
	for !INPUT_DONE() {
		PROCESS_PARA()
	}
	if !FIRST_RECORD() {
		DEPT_BREAK_PARA()
	}
	CLOSE_EMP()
	GRAND_PARA()
}

func INPUT_DONE() bool { return WsEofFlag == "Y" }
func FIRST_RECORD() bool { return WsFirstFlag == "Y" }

func OPEN_EMP() {
	f, err := os.Open("input.dat")
	if err != nil {
		// if file not exists, treat as empty (EOF immediately)
		// still need to handle close gracefully
		empFile = nil
		empReader = nil
		return
	}
	empFile = f
	empReader = bufio.NewReader(f)
}

func CLOSE_EMP() {
	if empFile != nil {
		empFile.Close()
	}
}

func READ_PARA() {
	if empReader == nil {
		WsEofFlag = "Y"
		return
	}
	line, err := empReader.ReadString('\n')
	if err != nil {
		// EOF or error: check if we got data before EOF
		if len(line) == 0 {
			WsEofFlag = "Y"
			return
		}
		// got last line without newline
	}
	// strip trailing \n and \r
	line = strings.TrimRight(line, "\r\n")
	// pad with spaces to 17 on right if shorter
	if len(line) < 17 {
		line = line + strings.Repeat(" ", 17-len(line))
	} else if len(line) > 17 {
		line = line[:17]
	}
	// parse
	ErId := line[0:5]
	ErDept := line[5:8]
	ErHoursStr := line[8:12]
	ErRateStr := line[12:17]

	EmpRecVar.ErId = ErId
	EmpRecVar.ErDept = ErDept
	EmpRecVar.ErHours = parsePIC9(ErHoursStr, 1)
	EmpRecVar.ErRate = parsePIC9(ErRateStr, 2)
}

func parsePIC9(s string, scale int32) decimal.Decimal {
	s = strings.TrimSpace(s)
	if s == "" {
		return decimal.NewFromInt(0)
	}
	// digits only
	// remove any non-digit (should not happen)
	filtered := ""
	for _, c := range s {
		if c >= '0' && c <= '9' {
			filtered += string(c)
		}
	}
	if filtered == "" {
		return decimal.NewFromInt(0)
	}
	d, err := decimal.NewFromString(filtered)
	if err != nil {
		return decimal.NewFromInt(0)
	}
	d = d.Shift(-scale)
	return d
}

// helper to store with overflow and truncation/rounding
func storeTruncate(val decimal.Decimal, scale int32, intDigits int) decimal.Decimal {
	// truncate toward zero to scale
	v := val.Truncate(scale)
	v = applyOverflow(v, scale, intDigits)
	return v
}
func storeRounded(val decimal.Decimal, scale int32, intDigits int) decimal.Decimal {
	v := val.Round(scale)
	v = applyOverflow(v, scale, intDigits)
	return v
}
func applyOverflow(v decimal.Decimal, scale int32, intDigits int) decimal.Decimal {
	totalDigits := int64(intDigits) + int64(scale)
	if totalDigits <= 0 {
		return v
	}
	// compute mod = 10^totalDigits
	mod := decimal.NewFromInt(1).Shift(int32(totalDigits)) // 10^totalDigits
	// scaled integer
	scaled := v.Shift(scale) // integer value
	absScaled := scaled.Abs()
	if absScaled.Cmp(mod) < 0 {
		return v
	}
	rem := absScaled.Mod(mod)
	if v.IsNegative() {
		rem = rem.Neg()
	}
	return rem.Shift(-scale)
}

func PROCESS_PARA() {
	if FIRST_RECORD() {
		WsPrevDept = EmpRecVar.ErDept
		WsFirstFlag = "N"
	} else {
		if EmpRecVar.ErDept != WsPrevDept {
			DEPT_BREAK_PARA()
			WsPrevDept = EmpRecVar.ErDept
		}
	}
	PAY_PARA()
	READ_PARA()
}

func PAY_PARA() {
	// EVALUATE TRUE WHEN ER-HOURS >40
	if EmpRecVar.ErHours.Cmp(decimal.NewFromInt(40)) > 0 {
		WsRegHours = storeTruncate(decimal.NewFromInt(40), 1, 3)
		WsOtHours = storeTruncate(EmpRecVar.ErHours.Sub(decimal.NewFromInt(40)), 1, 3)
	} else {
		WsRegHours = storeTruncate(EmpRecVar.ErHours, 1, 3)
		WsOtHours = storeTruncate(decimal.NewFromInt(0), 1, 3)
	}
	// COMPUTE WS-GROSS ROUNDED = WS-REG-HOURS * ER-RATE + WS-OT-HOURS * ER-RATE *1.5
	onePointFive := decimal.NewFromInt(15).Shift(-1) // 1.5
	computed := WsRegHours.Mul(EmpRecVar.ErRate).Add(WsOtHours.Mul(EmpRecVar.ErRate).Mul(onePointFive))
	WsGross = storeRounded(computed, 2, 7)

	WsDeptTotal = storeTruncate(WsDeptTotal.Add(WsGross), 2, 9)
	WsDeptCount = WsDeptCount + 1
	// keep low-order 3 digits for count overflow (PIC 9(3))
	if WsDeptCount > 999 {
		WsDeptCount = WsDeptCount % 1000
	}
	WsGrandTotal = storeTruncate(WsGrandTotal.Add(WsGross), 2, 11)
	WsGrandCount = WsGrandCount + 1
	if WsGrandCount > 99999 {
		WsGrandCount = WsGrandCount % 100000
	}

	WsHoursEd = formatEdited(EmpRecVar.ErHours, "ZZ9.9")
	WsRateEd = formatEdited(EmpRecVar.ErRate, "ZZ9.99")
	WsGrossEd = formatEdited(WsGross, "Z,ZZZ,ZZ9.99")
	fmt.Printf("%s %s %s %s %s\n", EmpRecVar.ErId, EmpRecVar.ErDept, WsHoursEd, WsRateEd, WsGrossEd)
}

func DEPT_BREAK_PARA() {
	WsDeptEd = formatEdited(WsDeptTotal, "ZZZ,ZZZ,ZZ9.99")
	// DISPLAY "  DEPT " WS-PREV-DEPT " EMPLOYEES: " WS-DEPT-COUNT " TOTAL: " WS-DEPT-ED
	// WS-DEPT-COUNT is PIC 9(3) unedited? In DISPLAY, it's numeric unedited -> zero-padded to 3 digits?
	// But spec says: An unedited numeric DISPLAY item such as PIC 9(5) prints zero-padded to its digit count.
	// So WS-DEPT-COUNT should be 3 digits zero-padded.
	// COBOL DISPLAY of numeric item without editing typically prints as is, but spec says zero-padded.
	// We'll format as %03d
	countStr := fmt.Sprintf("%03d", WsDeptCount)
	fmt.Printf("  DEPT %s EMPLOYEES: %s TOTAL: %s\n", WsPrevDept, countStr, WsDeptEd)
	WsDeptTotal = decimal.NewFromInt(0)
	WsDeptCount = 0
}

func GRAND_PARA() {
	WsGrandEd = formatEdited(WsGrandTotal, "ZZ,ZZZ,ZZZ,ZZ9.99")
	countStr := fmt.Sprintf("%05d", WsGrandCount)
	fmt.Printf("GRAND TOTAL (%s): %s\n", countStr, WsGrandEd)
}

// generic edited formatting
func formatEdited(val decimal.Decimal, pic string) string {
	dotIdx := strings.Index(pic, ".")
	var intPic, decPic string
	if dotIdx >= 0 {
		intPic = pic[:dotIdx]
		decPic = pic[dotIdx+1:]
	} else {
		intPic = pic
		decPic = ""
	}
	decDigits := 0
	for _, c := range decPic {
		if c == 'Z' || c == '9' || c == '0' {
			decDigits++
		}
	}
	intDigits := 0
	for _, c := range intPic {
		if c == 'Z' || c == '9' || c == '0' {
			intDigits++
		}
	}
	// absolute
	neg := val.IsNegative()
	absVal := val
	if neg {
		absVal = val.Neg()
	}
	// StringFixed rounds; we need exact to decDigits, but rounding already done for stored values
	s := absVal.StringFixed(int32(decDigits))
	// split
	var intStrFull, fracStr string
	if decDigits > 0 {
		parts := strings.SplitN(s, ".", 2)
		intStrFull = parts[0]
		if len(parts) > 1 {
			fracStr = parts[1]
		} else {
			fracStr = ""
		}
		// pad frac
		if len(fracStr) < decDigits {
			fracStr = fracStr + strings.Repeat("0", decDigits-len(fracStr))
		} else if len(fracStr) > decDigits {
			fracStr = fracStr[:decDigits]
		}
	} else {
		intStrFull = s
		// remove any dot
		if idx := strings.Index(intStrFull, "."); idx >= 0 {
			intStrFull = intStrFull[:idx]
		}
		fracStr = ""
	}
	// handle negative sign removal for now (pics have no sign)
	// overflow drop high-order integer digits
	if len(intStrFull) > intDigits {
		intStrFull = intStrFull[len(intStrFull)-intDigits:]
	}
	// pad left with zeros to intDigits
	if len(intStrFull) < intDigits {
		intStrFull = strings.Repeat("0", intDigits-len(intStrFull)) + intStrFull
	}
	intDigitsStr := intStrFull // length intDigits

	// build output array from pic
	out := []rune(pic)
	// collect int positions
	intPositions := []int{}
	for i, c := range pic {
		if dotIdx >= 0 && i > dotIdx {
			// dec part handled separately, but we still need dec positions
			continue
		}
		if c == 'Z' || c == '9' || c == '0' {
			// only count if before dot (int part)
			if dotIdx < 0 || i < dotIdx {
				intPositions = append(intPositions, i)
			}
		}
	}
	decPositions := []int{}
	if dotIdx >= 0 {
		for i, c := range pic {
			if i <= dotIdx {
				continue
			}
			if c == 'Z' || c == '9' || c == '0' {
				decPositions = append(decPositions, i)
			}
		}
	}
	// fill int digits
	for idx, pos := range intPositions {
		ch := intDigitsStr[idx]
		out[pos] = rune(ch)
	}
	// fill dec digits
	for idx, pos := range decPositions {
		if idx < len(fracStr) {
			out[pos] = rune(fracStr[idx])
		} else {
			out[pos] = '0'
		}
	}
	// Z suppression
	// find first non-zero index in intDigitsStr
	firstNZ := -1
	for i, ch := range intDigitsStr {
		if ch != '0' {
			firstNZ = i
			break
		}
	}
	if firstNZ == -1 {
		// all zeros -> keep last digit
		firstNZ = intDigits - 1
	}
	posFirstNZ := -1
	if firstNZ >= 0 && firstNZ < len(intPositions) {
		posFirstNZ = intPositions[firstNZ]
	}
	// for each int position with digit idx < firstNZ, if pic char Z -> space
	for idx, pos := range intPositions {
		if idx < firstNZ {
			orig := rune(pic[pos])
			if orig == 'Z' {
				out[pos] = ' '
			} else if orig == '9' || orig == '0' {
				// keep '0' ? but if it's before firstNZ and is 9, should it still be space? Actually 9 prints 0.
				// For our rule, firstNZ defined on digits, includes 9 positions, so idx < firstNZ means those zeros are leading,
				// but if pic char is 9, we should keep '0' (COBOL 9 always prints). However our firstNZ logic already ensures that
				// the last 9 position is not suppressed when all zeros. Leading 9s before last would be suppressed? But our pics have
				// only one trailing 9, so not an issue. Keep as is.
				// leave as '0'
			}
		}
	}
	// commas in suppressed zone become spaces
	if posFirstNZ != -1 {
		for i, c := range out {
			if c == ',' {
				// check if this comma is in int part and before firstNZ
				if dotIdx >= 0 && i > dotIdx {
					continue
				}
				if i < posFirstNZ {
					out[i] = ' '
				}
			}
		}
	} else {
		// no integer digits? shouldn't happen
	}
	return string(out)
}
